
create table if not exists private.source_category_mappings_pre_full_review_20260802
as
select m.*, now() as snapshot_at
from public.source_category_mappings m
where false;

revoke all on table private.source_category_mappings_pre_full_review_20260802 from public, anon, authenticated;

select m.*, now()
from public.source_category_mappings m
where m.mapping_status='review_required'
  and not exists (
    select 1 from private.source_category_mappings_pre_full_review_20260802 b
    where b.source_category_id=m.source_category_id
  );

create temporary table tmp_full_taxonomy_review (
 source_category_id uuid primary key,
 garment_type_code text,
 sleeve_code text,
 pants_code text,
 body_code text,
 outcome text not null,
 basis text not null,
 reason text not null,
 confidence text not null
) on commit drop;


do $$
begin
 if (select count(*) from tmp_full_taxonomy_review) <> 1822 then
   raise exception 'Expected 1822 review rows';
 end if;
 if exists (
   select 1 from tmp_full_taxonomy_review t
   left join public.source_category_mappings m on m.source_category_id=t.source_category_id
   where m.source_category_id is null or m.mapping_status <> 'review_required'
 ) then
   raise exception 'Review target drift detected';
 end if;
 if exists (
   select 1 from tmp_full_taxonomy_review t
   left join public.garment_types gt on gt.code=t.garment_type_code
   where t.garment_type_code is not null and gt.id is null
 ) then
   raise exception 'Unknown garment type code';
 end if;
 if exists (
   select 1 from tmp_full_taxonomy_review t
   where t.outcome not in ('confirmed','review_required','rejected')
 ) then
   raise exception 'Invalid outcome';
 end if;
end $$;

update public.source_category_mappings m
set garment_type_id = (select gt.id from public.garment_types gt where gt.code=t.garment_type_code),
    default_sleeve_class_code = t.sleeve_code,
    default_pants_length_code = t.pants_code,
    default_body_length_code = t.body_code,
    resolution_mode = case when t.outcome='review_required' and t.garment_type_code is null then 'unresolved' else 'explicit_original_path' end,
    mapping_status = t.outcome,
    evidence = coalesce(m.evidence,'{}'::jsonb) || jsonb_build_object(
      'taxonomy_full_review',
      jsonb_build_object(
        'batch','full_review_1822_v1',
        'reviewed_on','2026-08-02',
        'review_scope','all_previous_review_required_rows',
        'outcome',t.outcome,
        'garment_type_candidate',t.garment_type_code,
        'sleeve_class',t.sleeve_code,
        'pants_length_class',t.pants_code,
        'body_length_class',t.body_code,
        'basis',t.basis,
        'reason',t.reason,
        'confidence',t.confidence
      )
    ),
    policy_version = 'v2_taxonomy_full_review_20260802',
    updated_at = now()
from tmp_full_taxonomy_review t
where m.source_category_id=t.source_category_id;

update public.client_source_category_mappings c
set garment_type_id=m.garment_type_id,
    default_sleeve_class_code=m.default_sleeve_class_code,
    default_pants_length_code=m.default_pants_length_code,
    default_body_length_code=m.default_body_length_code,
    mapping_status=m.mapping_status,
    policy_version=m.policy_version,
    garment_type_code=(select gt.code from public.garment_types gt where gt.id=m.garment_type_id),
    updated_at=now()
from public.source_category_mappings m, tmp_full_taxonomy_review t
where c.source_category_id=m.source_category_id
  and t.source_category_id=m.source_category_id;

do $$
begin
 if (select count(*) from private.source_category_mappings_pre_full_review_20260802) <> 1822 then
   raise exception 'Snapshot row count mismatch';
 end if;
 if (select count(*) from public.source_category_mappings where evidence->'taxonomy_full_review'->>'batch'='full_review_1822_v1') <> 1822 then
   raise exception 'Applied row count mismatch';
 end if;
 if (select count(*) from tmp_full_taxonomy_review where outcome='confirmed') <> 770
    or (select count(*) from tmp_full_taxonomy_review where outcome='review_required') <> 492
    or (select count(*) from tmp_full_taxonomy_review where outcome='rejected') <> 560 then
   raise exception 'Outcome count mismatch';
 end if;
 if exists (
   select 1 from tmp_full_taxonomy_review t
   join public.source_category_mappings m on m.source_category_id=t.source_category_id
   where (t.outcome='confirmed' and m.garment_type_id is null)
      or (t.outcome='rejected' and (m.garment_type_id is not null or m.default_sleeve_class_code is not null or m.default_pants_length_code is not null or m.default_body_length_code is not null))
 ) then
   raise exception 'Outcome invariant mismatch';
 end if;
 if exists (
   select 1
   from public.source_category_mappings m
   join public.client_source_category_mappings c using (source_category_id)
   where m.garment_type_id is distinct from c.garment_type_id
      or m.default_sleeve_class_code is distinct from c.default_sleeve_class_code
      or m.default_pants_length_code is distinct from c.default_pants_length_code
      or m.default_body_length_code is distinct from c.default_body_length_code
      or m.mapping_status is distinct from c.mapping_status
      or m.policy_version is distinct from c.policy_version
      or (select gt.code from public.garment_types gt where gt.id=m.garment_type_id) is distinct from c.garment_type_code
 ) then
   raise exception 'Client mapping mismatch';
 end if;
end $$;

comment on table private.source_category_mappings_pre_full_review_20260802 is
'Pre-change snapshot of all 1,822 review_required mappings before full taxonomy review on 2026-08-02.';
;
